SELECT status, method, CASE WHEN amount >= 1720 THEN 'high' WHEN amount >= 770 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(CASE WHEN method = 'card' THEN 1 END) AS card_count, AVG(amount) AS avg_amount FROM payments WHERE amount >= 1350 AND TO_DATE(paid_at) < '2023-06-01' GROUP BY status, method, CASE WHEN amount >= 1720 THEN 'high' WHEN amount >= 770 THEN 'mid' ELSE 'low' END ORDER BY avg_amount DESC, amount_bucket;
